/*
 * Empower-X (Ocean Enterprise) Compute-to-Data entrypoint: solar irradiation curve of a location.
 *
 * Input: only parameters (no dataset needed), from /data/inputs/algoCustomData.json:
 *   latitude, longitude          location
 *   tilt, azimuth                plane to also compute irradiation on (e.g. a roof); default 30° south
 *   optimize_tilt                also search the tilt with the most annual irradiation (default true)
 *   hourly_output                write the 8,760 hourly values (default true)
 *
 * Output (/data/outputs):
 *   summary.json         annual and monthly totals, peak sun hours, optimal tilt
 *   irradiation_hourly.csv   8,760 hours: GHI, DHI, DNI, irradiation on the plane, air temperature
 *   typical_day.csv      average curve per hour for each month
 *   monthly.csv          monthly totals
 */
'use strict';

const fs = require('fs');
const path = require('path');
const C = SolarCore; // defined above by the bundled solar-core.js

const INPUTS = process.env.C2D_INPUTS || '/data/inputs';
const OUTPUTS = process.env.C2D_OUTPUTS || '/data/outputs';
const log = m => console.log(`[zertipower-irradiation] ${m}`);
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

const DEFAULTS = { latitude: 41.3874, longitude: 2.1686, tilt: 30, azimuth: 0, optimize_tilt: true, hourly_output: true };

function readParams() {
  let raw = {};
  const file = path.join(INPUTS, 'algoCustomData.json');
  if (fs.existsSync(file)) {
    try { raw = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (e) { log('Ignoring unreadable algoCustomData.json'); }
  }
  const p = { ...DEFAULTS };
  for (const [k, v] of Object.entries(raw)) {
    const key = k.trim().toLowerCase();
    if (key in DEFAULTS) p[key] = v; else log(`Unknown parameter ignored: ${k}`);
  }
  for (const k of ['latitude', 'longitude', 'tilt', 'azimuth']) {
    const v = typeof p[k] === 'string' ? parseFloat(p[k].replace(',', '.')) : Number(p[k]);
    p[k] = Number.isFinite(v) ? v : DEFAULTS[k];
  }
  for (const k of ['optimize_tilt', 'hourly_output']) {
    p[k] = p[k] === true || /^(true|1|yes|si|sí)$/i.test(String(p[k]));
  }
  p.tilt = Math.min(90, Math.max(0, p.tilt));
  p.azimuth = ((p.azimuth + 540) % 360) - 180;
  if (Math.abs(p.latitude) > 90 || Math.abs(p.longitude) > 180) throw new Error('latitude/longitude out of range');
  return p;
}

const sum = a => a.reduce((x, y) => x + y, 0);
const r = (v, d = 1) => Math.round(v * 10 ** d) / 10 ** d;

// ---- HTML report (self-contained page next to summary.json) ----------------
function compassOf(az) {
  // azimuth convention of this algorithm: 0 south, -90 east, 90 west, ±180 north
  const names = ['south', 'south-west', 'west', 'north-west', 'north', 'north-east', 'east', 'south-east'];
  return names[(((Math.round(az / 45)) % 8) + 8) % 8];
}

function renderReport(summary, dayRows, p) {
  const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const a = summary.annual, opt = summary.optimal_tilt, mon = summary.monthly;
  const lat = reportNum(summary.site.latitude, 2), lon = reportNum(summary.site.longitude, 2);
  const planeTxt = `${reportNum(summary.plane.tilt_deg, 1)}° tilt, facing ${compassOf(summary.plane.azimuth_deg)} (azimuth ${reportNum(summary.plane.azimuth_deg, 1)}°)`;

  // typical day: plane irradiance [month][hour] in W/m², parsed from the typical_day.csv rows
  const td = Array.from({ length: 12 }, () => new Array(24).fill(0));
  const tdGhi = Array.from({ length: 12 }, () => new Array(24).fill(0));
  dayRows.forEach((row) => {
    const v = String(row).split(',').map(Number);
    td[v[0] - 1][v[1]] = v[5];
    tdGhi[v[0] - 1][v[1]] = v[2];
  });
  const hours = Array.from({ length: 24 }, (_, h) => String(h).padStart(2, '0') + ':00');
  // trim the night hours that are dark in every month (keep one dark hour each side)
  const lit = (h) => td.some((row) => row[h] > 0) || tdGhi.some((row) => row[h] > 0);
  let firstLit = 0, lastLit = 23;
  while (firstLit < 23 && !lit(firstLit)) firstLit++;
  while (lastLit > firstLit && !lit(lastLit)) lastLit--;
  firstLit = Math.max(0, firstLit - 1); lastLit = Math.min(23, lastLit + 1);
  const span = (arr) => arr.slice(firstLit, lastLit + 1);

  const kpis = reportKpis([
    { label: 'Sun on flat ground (GHI)', value: reportNum(a.ghi_kwh_m2, 0), unit: 'kWh/m² per year', hint: 'Global horizontal irradiation' },
    { label: 'Sun on your panel plane', value: reportNum(a.plane_kwh_m2, 0), unit: 'kWh/m² per year', hint: `${reportNum(summary.plane.tilt_deg, 1)}° tilt, facing ${compassOf(summary.plane.azimuth_deg)}` },
    { label: 'Peak sun hours', value: reportNum(a.peak_sun_hours_per_day, 2), unit: 'h/day', hint: 'On the panel plane, yearly average' },
    opt
      ? { label: 'Best tilt for this orientation', value: reportNum(opt.tilt_deg, 0), unit: '°', hint: `${reportNum(opt.plane_kwh_m2, 0)} kWh/m² per year (${opt.gain_vs_selected >= 0 ? '+' : ''}${reportNum(opt.gain_vs_selected * 100, 1)} % vs your plane)` }
      : { label: 'Best tilt for this orientation', value: 'not computed', unit: '', hint: 'optimize_tilt was off' },
    { label: 'Site', value: `${lat}, ${lon}`, unit: '', hint: 'Latitude, longitude (°)' },
    { label: 'Panel plane', value: `${reportNum(summary.plane.tilt_deg, 1)}° / ${reportNum(summary.plane.azimuth_deg, 1)}°`, unit: '', hint: `Tilt / azimuth (0° = south), facing ${compassOf(summary.plane.azimuth_deg)}` },
    { label: 'Mean air temperature', value: reportNum(a.mean_temperature_c, 1), unit: '°C', hint: 'Yearly average' },
    { label: 'Diffuse share of GHI', value: reportNum(a.diffuse_fraction * 100, 1), unit: '%', hint: 'Light scattered by sky and clouds' },
  ]);
  // 8 tiles: force a 4 + 4 grid on desktop (the helper's default gives 5 + 3); still wraps on phones
  // + right-aligned, fixed-decimal monthly table (reportNum drops trailing zeros: 141 next to 167.2)
  const kpiGrid = '<style>.kpis{grid-template-columns:repeat(auto-fit,minmax(170px,1fr))}' +
    '.irr-fixed td+td,.irr-fixed th+th{text-align:right;font-variant-numeric:tabular-nums}</style>';
  const fx = (v, d) => (Number.isFinite(Number(v)) ? Number(v).toLocaleString('en-US', { minimumFractionDigits: d, maximumFractionDigits: d }) : '–');
  const far = summary.site.nearest_pvgis_point_km > 60
    ? ` Warning: the site is ${reportNum(summary.site.nearest_pvgis_point_km, 0)} km from the nearest embedded PVGIS point (Spain and Andorra), so these figures are only indicative.`
    : '';
  const monthName = (m) => MONTH_NAMES[MONTHS.indexOf(m)] || m;
  const s1 = reportSection('Summary', kpiGrid + kpis,
    `How much solar energy reaches this site in a typical year, on flat ground and on a plane of ${planeTxt}. ` +
    `Best month on the plane: ${monthName(summary.best_month)}; weakest: ${monthName(summary.worst_month)}.` + far);

  const s2 = reportSection('Month by month',
    reportBarChart({
      title: 'Monthly solar irradiation (kWh/m²)',
      categories: mon.map((m) => m.month),
      series: [
        { name: 'Flat ground (GHI)', values: mon.map((m) => m.ghi_kwh_m2), color: '#94a3b8' },
        { name: 'Panel plane', values: mon.map((m) => m.plane_kwh_m2), color: '#f59e0b' },
      ],
      unit: 'kWh/m²',
      note: (mon[0].plane_kwh_m2 + mon[11].plane_kwh_m2 > mon[0].ghi_kwh_m2 + mon[11].ghi_kwh_m2)
        ? 'A tilted plane facing the sun catches more of the low winter sun, so its advantage over flat ground is largest in winter.'
        : 'This plane receives less than flat ground in winter: its tilt and orientation do not face the low winter sun.',
    }) +
    '<div class="irr-fixed">' + reportTable({
      title: 'Monthly totals',
      columns: [
        { key: 'name', label: 'Month' },
        { key: 'ghi', label: 'GHI (kWh/m²)' },
        { key: 'plane', label: 'Plane (kWh/m²)' },
        { key: 'daily', label: 'Plane per day (kWh/m²)' },
        { key: 'temp', label: 'Mean temp. (°C)' },
        { key: 'peak', label: 'Peak GHI (W/m²)' },
      ],
      rows: mon.map((m, i) => ({
        name: MONTH_NAMES[i], ghi: fx(m.ghi_kwh_m2, 1), plane: fx(m.plane_kwh_m2, 1),
        daily: fx(m.plane_daily_kwh_m2, 2), temp: fx(m.mean_temperature_c, 1), peak: fx(m.peak_ghi_w_m2, 0),
      })),
      limit: 12,
    }) + '</div>',
    'Total solar energy per square metre in each month. Panel area × panel efficiency × the plane value gives a rough estimate of electricity.');

  const repMonths = [0, 3, 6, 9];
  const repColors = ['#2563eb', '#16a34a', '#f59e0b', '#dc2626'];
  const s3 = reportSection('A typical day',
    reportLineChart({
      title: 'Average irradiance on the panel plane through the day (W/m²)',
      labels: span(hours),
      series: repMonths.map((m, i) => ({ name: MONTH_NAMES[m], values: span(td[m]), color: repColors[i] })),
      unit: 'W/m²',
      note: 'Average over all days of each month, local clock time (Europe/Madrid, summer time included).',
    }) +
    reportHeatmap({
      title: 'Panel-plane irradiance by month and hour (W/m²)',
      rows: MONTH_NAMES,
      cols: span(hours).map((h) => h.slice(0, 2)),
      values: td.map(span),
      unit: 'W/m²',
      note: 'Columns are the hour of the day (local clock time); deeper blue means more sunshine on the panels.',
    }),
    'How sunshine is spread over the hours of the day, for four representative months and for every month. ' +
    `The highest monthly-average hour reaches ${reportNum(Math.max(...td.flat()), 0)} W/m² on the plane and ${reportNum(Math.max(...tdGhi.flat()), 0)} W/m² on flat ground.`);

  const s4 = reportSection('Direct and diffuse light',
    reportDonut({
      title: 'Annual irradiation on flat ground by type (kWh/m²)',
      slices: [
        { label: 'Direct (beam) sunlight', value: Math.max(0, a.ghi_kwh_m2 - a.dhi_kwh_m2), color: '#f59e0b' },
        { label: 'Diffuse (sky) light', value: a.dhi_kwh_m2, color: '#60a5fa' },
      ],
      unit: 'kWh/m²',
      note: `Direct normal irradiation (DNI, measured on a surface always facing the sun) is ${reportNum(a.dni_kwh_m2, 0)} kWh/m² per year.`,
    }),
    'Direct light comes straight from the sun and depends on orientation; diffuse light is scattered by clouds and sky and reaches panels from all directions.');

  const params = [
    { k: 'Latitude, longitude (rounded)', v: `${lat}°, ${lon}°` },
    { k: 'Plane tilt', v: `${reportNum(summary.plane.tilt_deg, 1)}° (0° = flat, 90° = vertical)` },
    { k: 'Plane azimuth', v: `${reportNum(summary.plane.azimuth_deg, 1)}° (${compassOf(summary.plane.azimuth_deg)}; 0 = south, -90 = east, 90 = west)` },
    { k: 'Search best tilt', v: p.optimize_tilt ? 'yes (1° steps)' : 'no' },
    { k: 'Hourly file written', v: p.hourly_output ? `yes (irradiation_hourly.csv, ${reportNum(C.CAL.length, 0)} hours)` : 'no' },
    { k: 'Distance to nearest PVGIS point', v: `${reportNum(summary.site.nearest_pvgis_point_km, 1)} km` },
    { k: 'Data source', v: summary.site.data },
    { k: 'Calendar', v: `${summary.calendar_year}, ${summary.timezone}` },
  ];
  const s5 = reportSection('Parameters and method',
    reportTable({ title: 'Settings used', columns: [{ key: 'k', label: 'Setting' }, { key: 'v', label: 'Value' }], rows: params, limit: 20 }) +
    '<p class="note">Files next to this report: summary.json (all totals), monthly.csv, typical_day.csv' +
    (p.hourly_output ? ', irradiation_hourly.csv' : '') + '. Values are long-term averages, not a forecast for a specific year.</p>',
    'Monthly averages from PVGIS are spread hour by hour with solar geometry and projected onto the panel plane.');

  return reportPage({
    title: 'Solar irradiation curve',
    subtitle: `Site ${lat}°, ${lon}° · plane ${planeTxt} · Zertipower / Empower-X`,
    sections: [s1, s2, s3, s4, s5],
    jsonFile: 'summary.json',
  });
}

function main() {
  const started = Date.now();
  fs.mkdirSync(OUTPUTS, { recursive: true });
  const p = readParams();
  const site = C.siteAt(p.latitude, p.longitude);
  log(`Site ${p.latitude}, ${p.longitude} (nearest PVGIS point ${site.nearestKm.toFixed(0)} km), plane ${p.tilt}° / azimuth ${p.azimuth}°`);
  if (site.nearestKm > 60) log('Warning: the location is far from the embedded PVGIS data (Spain and Andorra); results are indicative');

  const res = C.production(site, [{ kwp: 1, tilt: p.tilt, azimuth: p.azimuth }], {});
  const { ghi, dhi, dni, poa, temp } = res;

  // optimal tilt for this orientation (1° steps)
  let optimal = null;
  if (p.optimize_tilt) {
    for (let t = 0; t <= 90; t++) {
      const y = sum(C.production(site, [{ kwp: 1, tilt: t, azimuth: p.azimuth }], {}).poa);
      if (!optimal || y > optimal.poa) optimal = { tilt: t, poa: y };
    }
  }

  // monthly
  const monthly = MONTHS.map(() => ({ ghi: 0, dhi: 0, dni: 0, poa: 0, temp: 0, hours: 0, peak: 0 }));
  C.CAL.forEach((c, i) => {
    const m = monthly[c.m];
    m.ghi += ghi[i]; m.dhi += dhi[i]; m.dni += dni[i]; m.poa += poa[i]; m.temp += temp[i]; m.hours++;
    m.peak = Math.max(m.peak, ghi[i]);
  });
  const monthRows = monthly.map((m, i) => ({
    month: MONTHS[i],
    ghi_kwh_m2: r(m.ghi), dhi_kwh_m2: r(m.dhi), dni_kwh_m2: r(m.dni), plane_kwh_m2: r(m.poa),
    ghi_daily_kwh_m2: r(m.ghi / C.DAYS_IN_MONTH[i], 2), plane_daily_kwh_m2: r(m.poa / C.DAYS_IN_MONTH[i], 2),
    mean_temperature_c: r(m.temp / m.hours), peak_ghi_w_m2: Math.round(m.peak * 1000),
  }));
  const best = monthRows.reduce((a, b) => (b.plane_kwh_m2 > a.plane_kwh_m2 ? b : a));
  const worst = monthRows.reduce((a, b) => (b.plane_kwh_m2 < a.plane_kwh_m2 ? b : a));

  const summary = {
    algorithm: 'Zertipower solar irradiation curve',
    version: '1.0.0',
    site: {
      latitude: p.latitude, longitude: p.longitude, nearest_pvgis_point_km: r(site.nearestKm),
      data: 'PVGIS SARAH-2 monthly irradiation and temperature, 2011-2020 average, interpolated; hourly curve modelled',
    },
    plane: { tilt_deg: p.tilt, azimuth_deg: p.azimuth, azimuth_convention: '0 south, -90 east, 90 west' },
    annual: {
      ghi_kwh_m2: r(sum(ghi), 0), dhi_kwh_m2: r(sum(dhi), 0), dni_kwh_m2: r(sum(dni), 0), plane_kwh_m2: r(sum(poa), 0),
      peak_sun_hours_per_day: r(sum(poa) / 365, 2),
      mean_temperature_c: r(sum(temp) / temp.length),
      diffuse_fraction: r(sum(dhi) / sum(ghi), 3),
    },
    optimal_tilt: optimal ? { tilt_deg: optimal.tilt, azimuth_deg: p.azimuth, plane_kwh_m2: r(optimal.poa, 0), gain_vs_selected: r(optimal.poa / sum(poa) - 1, 3) } : null,
    best_month: best.month, worst_month: worst.month,
    monthly: monthRows,
    calendar_year: C.YEAR, timezone: 'Europe/Madrid (local clock time)',
    elapsed_seconds: 0,
  };
  summary.elapsed_seconds = (Date.now() - started) / 1000;
  fs.writeFileSync(path.join(OUTPUTS, 'summary.json'), JSON.stringify(summary, null, 2));

  fs.writeFileSync(path.join(OUTPUTS, 'monthly.csv'),
    ['month,ghi_kwh_m2,dhi_kwh_m2,dni_kwh_m2,plane_kwh_m2,ghi_daily_kwh_m2,plane_daily_kwh_m2,mean_temperature_c,peak_ghi_w_m2',
      ...monthRows.map(m => Object.values(m).join(','))].join('\n') + '\n');

  const day = [];
  for (let m = 0; m < 12; m++) {
    const acc = Array.from({ length: 24 }, () => [0, 0, 0, 0, 0]);
    C.CAL.forEach((c, i) => { if (c.m === m) { const a = acc[c.h]; a[0] += ghi[i]; a[1] += dhi[i]; a[2] += dni[i]; a[3] += poa[i]; a[4] += temp[i]; } });
    const n = C.DAYS_IN_MONTH[m];
    acc.forEach((a, h) => day.push([m + 1, h, ...a.slice(0, 4).map(v => Math.round((v / n) * 1000)), (a[4] / n).toFixed(1)].join(',')));
  }
  fs.writeFileSync(path.join(OUTPUTS, 'typical_day.csv'), 'month,hour,ghi_w_m2,dhi_w_m2,dni_w_m2,plane_w_m2,temperature_c\n' + day.join('\n') + '\n');

  if (p.hourly_output) {
    const rows = ['local_datetime,ghi_w_m2,dhi_w_m2,dni_w_m2,plane_w_m2,temperature_c'];
    C.CAL.forEach((c, i) => {
      const dt = `${C.YEAR}-${String(c.m + 1).padStart(2, '0')}-${String(c.d).padStart(2, '0')}T${String(c.h).padStart(2, '0')}:00`;
      rows.push([dt, Math.round(ghi[i] * 1000), Math.round(dhi[i] * 1000), Math.round(dni[i] * 1000), Math.round(poa[i] * 1000), temp[i].toFixed(1)].join(','));
    });
    fs.writeFileSync(path.join(OUTPUTS, 'irradiation_hourly.csv'), rows.join('\n') + '\n');
  }
  reportWrite(fs, path.join(OUTPUTS, 'solar_irradiation_report.html'), () => renderReport(summary, day, p));
  log(`Done in ${summary.elapsed_seconds} s: GHI ${summary.annual.ghi_kwh_m2} kWh/m2, plane ${summary.annual.plane_kwh_m2} kWh/m2` +
    (optimal ? `, optimal tilt ${optimal.tilt}°` : ''));
  return 0;
}

try { process.exitCode = main(); } catch (e) { console.error(e); process.exitCode = 1; }
